#!/bin/sh
# creates the local secrets file for the dev stack if it does not exist yet.
# an existing file is never touched, because the umami admin password in it
# must keep matching the one already set in the database volume.
set -eu

env_file="${1:?usage: gen-env.sh <path>}"

if [ -f "$env_file" ]; then
  exit 0
fi

# hex keeps the values safe inside postgres urls without escaping
rand() { od -An -tx1 -N"$1" /dev/urandom | tr -d ' \n'; }

umask 077
cat >"$env_file" <<EOF
# local dev secrets, generated by deploy/compose/gen-env.sh. never commit.
POSTGRES_PASSWORD=$(rand 24)
UMAMI_DB_PASSWORD=$(rand 24)
UMAMI_APP_SECRET=$(rand 32)
UMAMI_URL=http://localhost:3000
UMAMI_ADMIN_PASSWORD=$(rand 24)
EOF
echo "created $env_file with new random secrets"
